class KontèPaj extends StatefulWidget {
  @override
  _KontèPajState createState() => _KontèPajState();
}

class _KontèPajState extends State<KontèPaj> {
  int _kontè = 0;

  void _metePlis() {
    setState(() { _kontè++; });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(child: Text('Kontè: $_kontè')),
      floatingActionButton: FloatingActionButton(
        onPressed: _metePlis,
        child: Icon(Icons.add),
      ),
    );
  }
}

