import 'package:http/http.dart' as http;

Future<String> chajeNon() async {
  final r = await http.get(Uri.parse('https://api.example.com/yo'));
  return r.body;
}

FutureBuilder<String>(
  future: chajeNon(),
  builder: (context, snapshot) {
    if (snapshot.connectionState == ConnectionState.waiting)
      return CircularProgressIndicator();
    if (snapshot.hasError) return Text('Erè!');
    return Text('Non: ${snapshot.data}');
  },
)

final kle = GlobalKey<FormState>();

Form(
  key: kle,
  child: Column(
    children: [
      TextFormField(
        decoration: InputDecoration(labelText: 'Imèl'),
        keyboardType: TextInputType.emailAddress,
        validator: (v) {
          if (v == null || v.isEmpty) return 'Imèl obligatwa';
          if (!v.contains('@')) return 'Imèl pa valid';
          return null;
        },
      ),
      ElevatedButton(
        onPressed: () { if (kle.currentState!.validate()) print('OK'); },
        child: Text('Voye'),
      ),
    ],
  ),
)

