class SèkDesen extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final penti = Paint()..color = Colors.blue;
    final sant = Offset(size.width / 2, size.height / 2);
    canvas.drawCircle(sant, 50, penti);
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => false;
}

